from typing import List, Tuple
from collections import defaultdict

def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    adjacency_list = defaultdict(set)
    for node1, node2 in reversed(edges):
        adjacency_list[node1].add(node2)
        adjacency_list[node2].add(node1)

    children = [0] * N
    for node in range(N):
        children[node] = len(adjacency_list[node])

    result = 0
    min_grouped_nodes = min(children)
    for node in range(N):
        if len(adjacency_list[node]) == min_grouped_nodes:
            for child in adjacency_list[node]:
                if len(adjacency_list[child]) < min_grouped_nodes-1:
                    result += children[child]

    return result
